import test from 'node:test';
import assert from 'node:assert/strict';
import { createEngineeringPackage, toSvg, toDxf, exportArtifacts, csv, fromDrawDoc, fromPlannerGeometry, fromCandidateIR } from '../src/index.mjs';
import { fixture, sourceDoc } from './helpers.mjs';
test('export includes per-discipline drawings, schedules and honest register', async () => { const p = fixture(), r = await createEngineeringPackage(p), files = await exportArtifacts(p, r); assert.ok(files.has('drawings/L1-electrical.svg')); assert.ok(files.has('drawings/L1-combined.dxf')); assert.ok(files.has('schedules/hvac-zones.csv')); const reg = JSON.parse(files.get('drawing-register.json')); assert.equal(reg.constructionApproved, false); assert.equal(reg.inputHash, r.inputHash); });
test('SVG quotes user labels and retains input binding', async () => { const p = fixture(); p.architecture.rooms[0].name = '<script>alert(1)</script>'; const r = await createEngineeringPackage(p); const s = await toSvg(p, r); assert.ok(!s.includes('<script>')); assert.ok(s.includes('&lt;script&gt;')); assert.ok(s.includes(r.inputHash)); });
test('DXF records metre units and true subfloor drain elevations', async () => { const p = fixture(), r = await createEngineeringPackage(p), s = await toDxf(p, r); assert.ok(s.includes('$INSUNITS\n70\n6\n')); assert.ok(s.includes('P-DRAIN')); assert.ok(s.includes('-0.342')); assert.ok(s.endsWith('0\nEOF\n')); const pairs = s.trimEnd().split('\n'); assert.equal(pairs.length % 2, 0); });
test('stale drawing export is rejected', async () => { const p = fixture(), r = await createEngineeringPackage(p); p.services.electrical.loads[0].position.x -= .2; await assert.rejects(toSvg(p, r), { code: 'STALE_RESULT' }); });
test('modified serialized output cannot be silently exported with an old result hash', async () => { const p = fixture(), original = await createEngineeringPackage(p), edited = structuredClone(original); edited.disciplines[0].devices[0].position.x++; await assert.rejects(toDxf(p, edited), { code: 'RESULT_INTEGRITY' }); });
test('CSV preserves blanks and quotes while preventing formula injection', () => { const s = csv(['a', 'b', 'c'], [{ a: '=1+1', b: 'a,"b', c: null }]); assert.ok(s.includes("'=1+1")); assert.ok(s.includes('"a,""b"')); assert.ok(s.endsWith(',\r\n')); });
test('draw adapter requires actual upstream topology and validator functions', async () => { await assert.rejects(fromDrawDoc(sourceDoc(), { projectId: 'X' }), { code: 'UPSTREAM_FUNCTION_REQUIRED' }); });
test('draw adapter rejects a nonzero north angle until a frame transform is provided', async () => { const d = sourceDoc(); d.north = .3; await assert.rejects(fromDrawDoc(d, { projectId: 'X', analyzeDoc() {}, validateDoc() {} }), { code: 'FRAME_TRANSFORM_REQUIRED' }); });
test('legacy adapter cannot silently validate without the native validator', async () => { await assert.rejects(fromPlannerGeometry({}, { projectId: 'X' }), { code: 'UPSTREAM_FUNCTION_REQUIRED' }); });
test('IR adapter requires existing envelope and request verification', async () => { await assert.rejects(fromCandidateIR({}, {}, { projectId: 'X' }), { code: 'UPSTREAM_FUNCTION_REQUIRED' }); });
